class Solution {
public:
    long long countSubarrays(vector<int>& nums, int minK, int maxK) {
        long long ans = 0;
        long long cur = 0;
        for (int x : nums) {
            if (x >= minK && x <= maxK) {
                ++cur;
            } else {
                cur = 0;
            }
            ans += cur;
        }
        return ans;
    }
};

