class Solution:
    def countSubarrays(self, nums: list[int], minK: int, maxK: int) -> int:
        ans = 0
        cur = 0
        for x in nums:
            if minK <= x <= maxK:
                cur += 1
            else:
                cur = 0
            ans += cur
        return ans

